import{_ as a}from"./chunks/go_signin_page.DptkCh_6.js";import{_ as t}from"./chunks/rbac_signin.CHQQwPoS.js";import{_ as s,o as i,c as o,a2 as r}from"./chunks/framework.Ce1WstT_.js";const c="/fundsroom_infotech/assets/architecture/authentication-flow.svg",n="/fundsroom_infotech/assets/architecture/rbac-architecture.svg",l="/fundsroom_infotech/assets/architecture/role-permission-matrix.svg",w=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"security/authentication.md","filePath":"security/authentication.md"}'),d={name:"security/authentication.md"};function h(u,e,p,m,v,f){return i(),o("div",null,[...e[0]||(e[0]=[r('<div class="page-header"><span class="category-badge">AUTHENTICATION &amp; SECURITY</span><h1>Role-Based Access Control</h1><p class="page-subtitle">Stateless JWT authentication enforcing strict operational boundaries across Admin, Sales, Warehouse, and Accounts workflows.</p><hr class="header-divider"></div><p>The system employs custom stateless JSON Web Tokens (JWT) for authentication, avoiding heavy dependencies on external identity providers while maintaining strict security control.</p><h2 id="authentication-flow" tabindex="-1">Authentication Flow <a class="header-anchor" href="#authentication-flow" aria-label="Permalink to &quot;Authentication Flow&quot;">​</a></h2><div class="architecture-container"><img src="'+c+'" alt="Authentication Architecture Flow"></div><p class="screenshot-caption">Figure 4 — Authentication &amp; Login Flow</p><ol><li>User POSTs email/password/selected role to <code>/api/v1/auth/login</code>.</li><li>Backend queries user, hashes password via <code>bcrypt</code>, and compares.</li><li>Backend strictly matches the selected role against the authoritative role in the database.</li><li>If successful, backend signs a JWT (expiring in 12 hours) containing <code>userId</code> and <code>role</code>.</li><li>Client stores JWT and attaches it as <code>Authorization: Bearer &lt;token&gt;</code> on all subsequent requests to access protected routes.</li></ol><h2 id="rbac-architecture" tabindex="-1">RBAC Architecture <a class="header-anchor" href="#rbac-architecture" aria-label="Permalink to &quot;RBAC Architecture&quot;">​</a></h2><div class="architecture-container"><img src="'+n+'" alt="RBAC Architecture Flow"></div><p class="screenshot-caption">Figure 5 — RBAC Authoritative Database Role Enforcement</p><p>The backend enforces access via <code>authorize([&#39;ROLE&#39;])</code> middleware, ensuring that the database remains the source of truth, regardless of the role selected by the user on the frontend.</p><h2 id="role-overview" tabindex="-1">Role Overview <a class="header-anchor" href="#role-overview" aria-label="Permalink to &quot;Role Overview&quot;">​</a></h2><div class="feature-grid"><div class="content-card"><h3><span class="role-badge admin">ADMIN</span></h3><p>Full operational control. Can view all modules, manage users, and view cross-functional data.</p></div><div class="content-card"><h3><span class="role-badge sales">SALES</span></h3><p>Customer and sales workflows. Can generate sales challans, but cannot modify inventory directly.</p></div><div class="content-card"><h3><span class="role-badge warehouse">WAREHOUSE</span></h3><p>Inventory and stock operations. Manages product catalog and stock adjustments. Cannot manage CRM.</p></div><div class="content-card"><h3><span class="role-badge accounts">ACCOUNTS</span></h3><p>Account-related workflows. Read-only verification access to Challans, Customers, and Products for auditing.</p></div></div><h2 id="permission-matrix" tabindex="-1">Permission Matrix <a class="header-anchor" href="#permission-matrix" aria-label="Permalink to &quot;Permission Matrix&quot;">​</a></h2><div class="architecture-container"><img src="'+l+'" alt="Role Permission Matrix"></div><p class="screenshot-caption">Figure 6 — Functional Permissions per Role</p><div class="info custom-block"><p class="custom-block-title">SEED DATA</p><p>The system comes seeded with default users for each of the four roles for testing purposes. Dynamic user creation is currently unsupported in the UI to maintain assignment scope.</p></div><h2 id="visual-reference" tabindex="-1">Visual Reference <a class="header-anchor" href="#visual-reference" aria-label="Permalink to &quot;Visual Reference&quot;">​</a></h2><div class="screenshot-grid"><div class="premium-screenshot"><div class="premium-screenshot-bar"><div class="browser-dot dot-red"></div><div class="browser-dot dot-yellow"></div><div class="browser-dot dot-green"></div></div><img src="'+a+'" alt="Login Screen"></div><div class="premium-screenshot"><div class="premium-screenshot-bar"><div class="browser-dot dot-red"></div><div class="browser-dot dot-yellow"></div><div class="browser-dot dot-green"></div></div><img src="'+t+'" alt="RBAC Credentials Hint"></div></div>',18)])])}const A=s(d,[["render",h]]);export{w as __pageData,A as default};
